<form class="filter-bar mb-3" method="get" action="<?= pl_e(pl_url('/parties')) ?>"><input type="hidden" name="role" value="<?= pl_e($filters['role']) ?>"><?php pl_ui_list_controls($filters); ?><button class="btn btn-secondary">Filter</button></form>
<div class="table-wrap"><table class="table"><caption class="sr-only">Customers and suppliers; balances in <?= pl_e($company['currency']) ?></caption><thead><tr><th scope="col"><?php pl_ui_sort('/parties',$filters,'name','Legal name'); ?></th><th scope="col">Role</th><th scope="col" class="text-end">Receivable</th><th scope="col" class="text-end">Payable</th></tr></thead><tbody>
