<div class="flex flex-col min-h-0 flex-1 overflow-y-auto px-5 pt-4"><?php pl_ui_tabs(['Details'=>'#party-details','Contacts'=>'#party-contacts','Activity'=>'#party-activity'],'Details',true); ?>
<section id="party-details" class="py-3" data-ui-tab-panel><dl class="dgrid"><?php foreach (['Trading name'=>$selection['trading_name']?:'—','Entity type'=>$selection['entity_type'],'Country'=>$selection['country_code'],'Currency'=>$selection['financial']['currency']??$company['currency'],'Payment terms'=>$selection['financial']['payment_terms']??'—'] as $label=>$value): ?><div class="dgrid-row"><dt><?= pl_e($label) ?></dt><dd><?= pl_e($value?:'—') ?></dd></div><?php endforeach; ?></dl></section>
<section id="party-contacts" class="py-3" data-ui-tab-panel><?php foreach ($contacts as $contact): ?><div class="border-b border-border py-3"><h3 class="text-sm font-semibold"><?= pl_e($contact['name']) ?></h3><p class="text-xs text-ink-muted"><?= pl_e($contact['role']) ?><?= $contact['is_primary']?' · Primary':'' ?></p><p class="text-sm"><?= pl_e($contact['email'].' · '.$contact['phones']) ?></p></div><?php endforeach; if (!$contacts): ?><p class="text-sm text-ink-muted">No contacts yet.</p><?php endif; ?></section>
<section id="party-activity" class="py-3" data-ui-tab-panel><p class="text-xs text-ink-muted mb-2">Latest 20 documents, including drafts.</p><dl class="dgrid"><?php foreach ($activity as $item): ?><div class="dgrid-row"><dt><a class="link" href="<?= pl_e(pl_url(in_array($item['kind'],['invoice','customer_credit'],true)?'/ar':'/ap',['id'=>$item['id']])) ?>"><?= pl_e($item['number']) ?></a></dt><dd><?= pl_e(ucfirst($item['payment_status']??$item['status']).' · '.$item['currency'].' '.pl_money($item['total'])) ?></dd></div><?php endforeach; if (!$activity): ?><div class="dgrid-row"><dt>Activity</dt><dd>No documents yet.</dd></div><?php endif; ?></dl></section></div>
<div class="panel-actions"><p class="panel-actions-note">One shared record for both roles.</p><a class="btn btn-secondary" href="<?= pl_e(pl_url('/parties',['id'=>$selection['id'],'return_filters'=>$filters])) ?>"><?= pl_icon('pencil') ?> <?= pl_can_write($company)?'Edit party':'View party' ?></a></div>
<?php }); ?></div></div>
